package io.localplayer.app

import android.content.pm.ActivityInfo
import android.content.res.Configuration
import androidx.activity.compose.setContent
import androidx.compose.runtime.*
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.test.*
import androidx.compose.ui.test.junit4.createAndroidComposeRule
import androidx.compose.ui.unit.Density
import androidx.lifecycle.ViewModelStore
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import java.io.File

class PortraitCabinet52RegressionTest{
    @get:Rule val ui=createAndroidComposeRule<MainActivity>()
    private fun player(scale:Float=1f){
        ui.runOnUiThread{ui.activity.requestedOrientation=ActivityInfo.SCREEN_ORIENTATION_PORTRAIT}
        ui.waitUntil(5000){ui.activity.resources.configuration.orientation==Configuration.ORIENTATION_PORTRAIT}
        ui.runOnUiThread{ui.activity.setContent{PlayerTheme{
            val d=LocalDensity.current
            CompositionLocalProvider(LocalDensity provides Density(d.density,scale)){
                FullscreenPlayer(null,"海边的旧影像 · 第38集",null,{},{},{},{},false,{},{} ,{})
            }
        }}}
    }
    @Test fun portraitKeepsWholeFrameAndHasOneCompactControlRow(){
        player(1.8f)
        ui.onNodeWithTag("video-scale-fit").assertExists()
        ui.onNodeWithTag("portrait-playback-rail").assertDoesNotExist()
        val toolbar=ui.onNodeWithTag("playback-toolbar").getUnclippedBoundsInRoot()
        val nodes=listOf(ui.onNodeWithTag("playback-speed"),ui.onNodeWithContentDescription("播放设置"),ui.onNodeWithContentDescription("选集"),ui.onNodeWithContentDescription("画面比例"),ui.onNodeWithContentDescription("旋转屏幕"))
        var edge=toolbar.left
        nodes.forEach{n->val b=n.assertIsDisplayed().getUnclippedBoundsInRoot();assertTrue(b.left>=edge);assertTrue(b.right<=toolbar.right);assertTrue((b.bottom-b.top).value>=48);edge=b.right}
        ui.onNodeWithContentDescription("画面比例").performClick()
        ui.onNodeWithTag("video-scale-fill").assertExists()
        ui.onNodeWithContentDescription("画面比例").performClick()
        ui.onNodeWithTag("video-scale-fit").assertExists()
        File(ui.activity.cacheDir,"portrait52-large.png").outputStream().use{androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().uiAutomation.takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,it)}
    }
    @Test fun portraitOverflowKeepsSecondaryActionsAndLocking(){
        player()
        ui.onNodeWithContentDescription("后台播放").assertDoesNotExist()
        ui.onNodeWithContentDescription("更多播放操作").performClick()
        ui.onNodeWithText("后台播放").assertIsDisplayed()
        ui.onNodeWithText("画中画").assertIsDisplayed().assertIsNotEnabled()
        ui.mainClock.autoAdvance=false
        ui.onNodeWithText("锁定方向与控件").performClick()
        ui.mainClock.advanceTimeByFrame()
        ui.onNodeWithTag("portrait-playback-controls").assertDoesNotExist()
        ui.onNodeWithTag("playback-gesture-surface").performTouchInput{click(Offset(width*.25f,height*.25f))}
        ui.mainClock.advanceTimeByFrame()
        ui.onNodeWithContentDescription("解锁方向与控件").performClick()
        ui.mainClock.advanceTimeByFrame()
        ui.mainClock.autoAdvance=true
        ui.onNodeWithTag("portrait-playback-controls").assertIsDisplayed()
    }
    @androidx.annotation.OptIn(androidx.media3.common.util.UnstableApi::class)
    @Test fun realPortraitFrameRetainsAspectAndShowsTransport(){
        player()
        lateinit var future:com.google.common.util.concurrent.ListenableFuture<androidx.media3.session.MediaController>
        ui.runOnUiThread{future=androidx.media3.session.MediaController.Builder(ui.activity,androidx.media3.session.SessionToken(ui.activity,android.content.ComponentName(ui.activity,PlaybackService::class.java))).buildAsync()}
        val c=future.get(10,java.util.concurrent.TimeUnit.SECONDS)
        try{
            val file=visualClip(false)
            lateinit var view:androidx.media3.ui.PlayerView
            ui.runOnUiThread{
                c.setMediaItem(androidx.media3.common.MediaItem.fromUri(android.net.Uri.fromFile(file)));c.prepare();c.pause()
                ui.activity.setContent{PlayerTheme{FullscreenPlayer(c,"片窗完整画面",null,{},{},{},{},false,{},{} ,{view=it})}}
            }
            ui.waitUntil(15000){var ready=false;ui.runOnUiThread{ready=c.playbackState==androidx.media3.common.Player.STATE_READY&&c.videoSize.width>0};ready}
            ui.onNodeWithContentDescription("播放").assertIsDisplayed()
            ui.onNodeWithContentDescription("后退10秒").assertIsDisplayed()
            ui.onNodeWithContentDescription("前进10秒").assertIsDisplayed()
            ui.runOnIdle{assertEquals(androidx.media3.ui.AspectRatioFrameLayout.RESIZE_MODE_FIT,view.resizeMode)}
            ui.runOnUiThread{c.play()}
            ui.waitUntil(5000){var progressed=false;ui.runOnUiThread{progressed=c.currentPosition>500};progressed}
            ui.runOnUiThread{c.pause()}
            Thread.sleep(300)
            File(ui.activity.cacheDir,"portrait52-real-landscape.png").outputStream().use{androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().uiAutomation.takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,it)}
            ui.runOnUiThread{c.setMediaItem(androidx.media3.common.MediaItem.fromUri(android.net.Uri.fromFile(visualClip(true))));c.prepare();c.pause()}
            ui.waitUntil(15000){var ready=false;ui.runOnUiThread{ready=c.playbackState==androidx.media3.common.Player.STATE_READY&&c.videoSize.height>c.videoSize.width};ready}
            ui.runOnUiThread{c.play()}
            ui.waitUntil(5000){var progressed=false;ui.runOnUiThread{progressed=c.currentPosition>500};progressed}
            ui.runOnUiThread{c.pause()}
            Thread.sleep(300)
            File(ui.activity.cacheDir,"portrait52-real-vertical.png").outputStream().use{androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().uiAutomation.takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,it)}
        }finally{ui.runOnUiThread{c.stop();c.clearMediaItems();c.release()}}
    }
    @Test fun cabinetRequiresContinuousThreeSecondsAndFiresOnlyOnce(){
        val owner=ViewModelStore();var opens=0
        try{
            ui.runOnUiThread{
                val vm=LibraryViewModel(ui.activity.application);owner.put("home",vm)
                ui.activity.setContent{PlayerTheme{HomeScreen(vm,{},{},{},{},onSealed={opens++})}}
            }
            val name=ui.onNodeWithTag("home-sealed-entry")
            name.performTouchInput{click()};ui.runOnIdle{assertEquals(0,opens)}
            name.performTouchInput{down(center);advanceEventTime(2900);up()};ui.runOnIdle{assertEquals(0,opens)}
            name.performTouchInput{down(center);advanceEventTime(1000);cancel()};ui.runOnIdle{assertEquals(0,opens)}
            name.performTouchInput{swipe(center,Offset(center.x,center.y+200),500)};ui.runOnIdle{assertEquals(0,opens)}
            name.performTouchInput{longClick(durationMillis=3100)};ui.runOnIdle{assertEquals(1,opens)}
            name.performTouchInput{longClick(durationMillis=6100)};ui.runOnIdle{assertEquals(2,opens)}
        }finally{ui.runOnUiThread{owner.clear()}}
    }
    // Original synthetic clips keep this rendering check independent of adb-injected files.
    private fun visualClip(vertical:Boolean)=File(ui.activity.cacheDir,if(vertical)"portrait52-vertical.mp4"else"portrait52-landscape.mp4").apply{
        writeBytes(android.util.Base64.decode(if(vertical)VERTICAL_CLIP else LANDSCAPE_CLIP,android.util.Base64.DEFAULT))
    }
    private companion object{
        const val LANDSCAPE_CLIP=""
        const val VERTICAL_CLIP=""
    }
}
